def decide(recipient_reputation, round_num, my_history):
    global _ema_rep, _ema_initialized, _ema_alpha

    # Update exponential moving average of recipient reputations
    if not _ema_initialized:
        _ema_rep = recipient_reputation
        _ema_initialized = True
    else:
        _ema_rep = _ema_alpha * recipient_reputation + (1 - _ema_alpha) * _ema_rep

    # Determine base threshold:
    # - First 10 rounds: fixed intermediate threshold (encourage early cooperation)
    # - Afterwards: use the EMA of recipient reputations, but with a small offset
    if round_num < 10:
        base = 0.5
    else:
        base = _ema_rep + 0.05   # Slightly more demanding as the game progresses

    # Adjust threshold based on our own past cooperation ratio:
    #   If we have cooperated more than half the time, be more generous (lower threshold)
    #   Otherwise be more cautious (higher threshold)
    if len(my_history) > 0:
        coop_ratio = sum(my_history) / len(my_history)
        adjustment = (coop_ratio - 0.5) * 0.5   # Stronger influence than original
        base -= adjustment

    # Clamp threshold to a sensible range [0.2, 0.8] to avoid extremes
    threshold = max(0.2, min(0.8, base))

    # Cooperate if recipient's reputation exceeds the threshold
    return recipient_reputation > threshold

